def check(x):
    b = [0] * (n + 100)
    for i in range(1, x + 1):
        x1 = mb[i][0]
        x2 = mb[i][1]
        b[x1] += 1
        b[x2 + 1] -= 1
    for i in range(1, n + 1):
        b[i] += b[i - 1]
        if b[i] > a[i]:
            return False
    return True

n, m = map(int, input().split())
