mb = [0] * (m + 1)
for i in range(1, m + 1):
    mb[i] = tuple(map(int, input().split()))

l = 0
r = m

while l < r:
    mid = (l + r + 1) // 2
    if check(mid):
        l = mid
    else:
        r = mid - 1

