**c++**

```cpp
#include <iostream>
#include <vector>

using namespace std;

int n, m;
vector<int> a, b;
vector<pair<int, int>> mb;

bool check(int x) {
    b = vector<int>(n + 100);
    for (int i = 1; i <= x; i++) {
        int x1 = mb[i].first;
        int x2 = mb[i].second;
        b[x1]++;
        b[x2 + 1]--;
    }
    for (int i = 1; i <= n; i++) {
        b[i] += b[i - 1];
        if (b[i] > a[i]) return false;
    }
    return true;
}

int main() {
    cin >> n >> m;
    a = vector<int>(n + 1);
    for (int i = 1; i <= n; i++) cin >> a[i];
    mb = vector<pair<int, int>>(m + 1);
    for (int i = 1; i <= m; i++) cin >> mb[i].first >> mb[i].second;
    int l = 0, r = m;
    while (l < r) {
        int mid = (l + r + 1) / 2;
        if (check(mid)) l = mid;
        else r = mid - 1;
    }
    cout << l << endl;
    return 0;
}
